const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Polygon([[
        [-74, -2], [-74, -14],
        [-60, -14], [-60, -2],
        [-74, -2]
    ]], null, false); // Western Brazil (Amazonas/Acre region)

    const startPeriod = { year: 2002, month: '08' };
    const endPeriod = { year: 2018, month: '08' };

    // 2. Data Acquisition & Check
    // Using MODIS Aqua Daily Aerosol Product. Band 'AOD_550_Dark_Target_Deep_Blue_Combined'
    // has a scale factor of 0.001. We will apply it.
    const collectionId = 'MODIS/061/MYD04_L2';
    const aodBand = 'AOD_550_Dark_Target_Deep_Blue_Combined';

    const getAodForPeriod = (year, month) => {
        const startDate = `${year}-${month}-01`;
        const endDate = ee.Date(startDate).advance(1, 'month');
        const collection = ee.ImageCollection(collectionId)
            .filterDate(startDate, endDate)
            .filterBounds(geometry)
            .select(aodBand);
        return collection;
    };

    const collection2002 = getAodForPeriod(startPeriod.year, startPeriod.month);
    const collection2018 = getAodForPeriod(endPeriod.year, endPeriod.month);

    const count2002 = collection2002.size().getInfo();
    const count2018 = collection2018.size().getInfo();

    if (count2002 === 0 || count2018 === 0) {
        console.log(`Image count for Aug 2002: ${count2002}`);
        console.log(`Image count for Aug 2018: ${count2018}`);
        console.log("C1: Empty Collection");
        return;
    }

    // 3. Processing
    const mean2002 = collection2002.mean().multiply(0.001); // Apply scale factor
    const mean2018 = collection2018.mean().multiply(0.001);

    // 4. Calculation
    const reduceArgs = {
        reducer: ee.Reducer.mean().setOutputs(['aod']),
        geometry: geometry,
        scale: 5000, // Use a coarse scale for regional average to avoid timeout
        maxPixels: 1e9,
    };

    const aod2002Result = mean2002.reduceRegion(reduceArgs).getInfo();
    const aod2018Result = mean2018.reduceRegion(reduceArgs).getInfo();

    const aod2002 = aod2002Result.aod;
    const aod2018 = aod2018Result.aod;

    // 5. Validation & Final Answer
    if (aod2002 === null || aod2018 === null) {
        console.log(`Aug 2002 AOD: ${aod2002}`);
        console.log(`Aug 2018 AOD: ${aod2018}`);
        console.log("C3: Calculation Failure");
        return;
    }

    // Check pixel counts to ensure the result is valid
    const pixelCount2002 = mean2002.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: 5000,
        maxPixels: 1e9
    }).get(aodBand).getInfo();

    const pixelCount2018 = mean2018.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: 5000,
        maxPixels: 1e9
    }).get(aodBand).getInfo();

    if (pixelCount2002 === 0 || pixelCount2018 === 0) {
        console.log(`Valid pixel count 2002: ${pixelCount2002}`);
        console.log(`Valid pixel count 2018: ${pixelCount2018}`);
        console.log("C2: No Valid Pixels");
        return;
    }

    console.log(`Image granules found for Aug 2002: ${count2002}`);
    console.log(`Image granules found for Aug 2018: ${count2018}`);
    console.log(`Mean Aerosol Optical Depth in Aug 2002: ${aod2002.toFixed(4)}`);
    console.log(`Mean Aerosol Optical Depth in Aug 2018: ${aod2018.toFixed(4)}`);

    if (aod2018 < aod2002) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log("D");
});
